function clToggle(el){const key=el&&el.dataset&&el.dataset.clKey;if(key)_clOpen[key]=!!el.open;}
function clKeep(fn){const e=$('#cllog');if(e)e.querySelectorAll('details[data-cl-key]').forEach(x=>clToggle(x));const top=e?e.scrollTop:0,bottom=e?Math.max(0,e.scrollHeight-e.scrollTop-e.clientHeight):0,atBottom=!!(e&&bottom<80);fn();render();const restore=()=>{const el=$('#cllog');if(!el)return;el.scrollTop=atBottom?Math.max(0,el.scrollHeight-el.clientHeight-bottom):Math.min(top,Math.max(0,el.scrollHeight-el.clientHeight));};restore();requestAnimationFrame(()=>{restore();requestAnimationFrame(restore);});}
//@@ web
function clDel(id,mid){const arr=msgs(id);const i=arr.findIndex(x=>x.id===mid);if(i<0)return;clKeep(()=>{callReplayClearAudio(arr[i]);if(arr[i]&&arr[i]._call&&arr[i].audio)clearVoiceAudio(arr[i]);arr.splice(i,1);save();});}
//@@ private
function clDel(id,mid){const arr=msgs(id),target=arr.find(x=>x.id===mid);if(!target)return;clKeep(()=>{const parentId=target._callTranslationOf||target.id;for(let i=arr.length-1;i>=0;i--){const m=arr[i],linked=m===target||m&&m._callTranslationOf===parentId;if(!linked)continue;callReplayClearAudio(m);if(m&&m._call&&m.audio)clearVoiceAudio(m);arr.splice(i,1);}save();});}
//@@ end
async function clDelSession(id,cs){if(!await uiConfirm('删除这一整通通话记录？'))return;clKeep(()=>{S.messages[mkey(id)]=msgs(id).filter(m=>{const del=m._call&&(m._cs||'')===cs;if(del){callReplayClearAudio(m);if(m.audio)clearVoiceAudio(m);}return !del;});save();});toast('已删这通');}
async function clClear(id){const sc=_clTab==='voice'?'语音':_clTab==='video'?'视频':'全部';if(!await uiConfirm('清空和ta的'+sc+'通话记录？\n（只删这一类的通话内容，不动文字聊天和记忆）'))return;
  S.messages[mkey(id)]=msgs(id).filter(m=>{if(!m._call)return true;const k=m._ck==='video'?'video':'voice',del=_clTab==='all'||k===_clTab;if(del){callReplayClearAudio(m);if(m.audio)clearVoiceAudio(m);}return !del;});save();render();toast(sc+'通话记录已清空');}
async function clClearOld(id){const sc=_clTab==='voice'?'语音':_clTab==='video'?'视频':'';const cut=Date.now()-86400000;
  if(!await uiConfirm('删掉一天前的'+sc+'通话记录？（只删这类、且超过24小时的）'))return;
  let n=0;S.messages[mkey(id)]=msgs(id).filter(m=>{if(!m._call)return true;if(m.time&&m.time>=cut)return true;if(_clTab!=='all'){const k=m._ck==='video'?'video':'voice';if(k!==_clTab)return true;}callReplayClearAudio(m);if(m.audio)clearVoiceAudio(m);n++;return false;});
  save();render();toast(n?'已删掉'+n+'条一天前的记录':'没有一天前的记录');}
/* ===== 线下约会（独立空间，与微信隔离）===== */
let _off=null;
/* ===== 线下外观 =====
   她说「线下也想要短信里那种透明磨砂高光气泡，圆润的，可以换背景，
   还能设置气泡和字体的颜色」。颜色存在角色身上（不是某一场约会上），
   所以换了场次、进共同生活也还是她挑的那一套。
   背景走和微信聊天背景同一个 compressChatBackground——2600px、质量 .93，
   她说过「换聊天背景不要压画质」。 */
/* OFF_ME_LIKE_TA_V1（2026-10-18 她说「我自己的那个气泡颜色也改成跟角色一样的颜色，默认颜色」）：我的气泡默认和 ta 的一样 */
const OFF_THEME_DEF={me:'#26262a',meInk:'#ffffff',them:'#26262a',themInk:'#ffffff',nar:'#c9c2b6'};
const OFF_THEME_WARM_ME='#d2c9ba';
/* OFF_BLACK_BG_V1：没换背景时用一张纯黑的图当背景（她说「默认是黑色背景图，纯黑的」）——液态玻璃要有背景图才画得出来，以前没背景时玻璃整个不出现，材质就变了 */
const OFF_BLACK_BG='data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAABAAAAAgCAIAAACU62+bAAAAFUlEQVR42mNgGAWjYBSMglEwCjABAAYgAAHw0JvSAAAAAElFTkSuQmCC';
const OFF_THEME_OLD_ME='#0a84ff';
function offColorOk(v,def){v=String(v||'').trim();return /^#[0-9a-fA-F]{6}$/.test(v)?v.toLowerCase():def;}
function offTheme(c){if(!c)return Object.assign({bg:'',skin:'glass'},OFF_THEME_DEF);
  const t=c.offTheme&&typeof c.offTheme==='object'&&!Array.isArray(c.offTheme)?c.offTheme:(c.offTheme={});
  t.bg=typeof t.bg==='string'?t.bg:'';
  /* OFF_GLASS_ONLY_V1（2026-10-18 她说「把原来的黑色文学风那个风格删掉，默认是这个磨砂玻璃」）：只剩玻璃，以前选过「原来的」也回到玻璃；没换背景时是纯黑 */
  t.skin='glass';
  for(const k in OFF_THEME_DEF)t[k]=offColorOk(t[k],OFF_THEME_DEF[k]);
  /* 我的气泡默认从那个蓝换回浅黄；只迁一次，自己挑过颜色的不动 */
  if(!t._meWarmV1){if(t.me===OFF_THEME_OLD_ME){t.me=OFF_THEME_DEF.me;t.meInk=OFF_THEME_DEF.meInk;}t._meWarmV1=1;}
  /* 还是以前默认浅黄（没自己挑过）的，换成新的默认（和 ta 一样）；只迁一次，自己挑过颜色的不动 */
  if(!t._meLikeTaV1){if(t.me===OFF_THEME_WARM_ME&&t.meInk==='#181614'){t.me=OFF_THEME_DEF.me;t.meInk=OFF_THEME_DEF.meInk;}t._meLikeTaV1=1;}
  return t;}
/* 线下和共同生活都只画最近这些条，其余留在存档里，点「看更早」再多放一段出来。
   一万条的时候整页重画要 90ms，每点一下按钮都要重画一次，就是她说的「点按钮很慢」。 */
const OFF_WINDOW_STEP=300;
let _offWindow={key:'',n:OFF_WINDOW_STEP};
function offWindowKey(id){return (_off&&_off.mode==='cohab'?'cohab:':'date:')+id;}
function offWindowSize(id){const k=offWindowKey(id);if(_offWindow.key!==k)_offWindow={key:k,n:OFF_WINDOW_STEP};return _offWindow.n;}
function offWindowRows(id,rows){rows=Array.isArray(rows)?rows.filter(m=>!m||m.role==='user'||m.who==='me'||m.source==='me'||!roleInternalControlLine(m.text||m.content)):[];const n=offWindowSize(id),hidden=Math.max(0,rows.length-n);
  return {rows:hidden?rows.slice(-n):rows,hidden,
    more:hidden?`<button type="button" class="off-more" onclick="offShowMore('${id}')">看更早的 ${hidden} 条</button>`:''};}
function offShowMore(id){const k=offWindowKey(id);_offWindow={key:k,n:(_offWindow.key===k?_offWindow.n:OFF_WINDOW_STEP)+OFF_WINDOW_STEP};
  // 往上加内容会把视线顶走，所以保住「离底部多远」而不是 scrollTop
  const b=$('#offbg'),keep=b?b.scrollHeight-b.scrollTop:null;render();
  const g=$('#offbg');if(g&&keep!=null)g.scrollTop=Math.max(0,g.scrollHeight-keep);}
function offRgba(hex,a){const h=String(hex||'').replace('#','');if(!/^[0-9a-fA-F]{6}$/.test(h))return '';
  const n=parseInt(h,16);return 'rgba('+((n>>16)&255)+','+((n>>8)&255)+','+(n&255)+','+a+')';}
function offStageAttrs(c){const t=offTheme(c),classic=t.skin==='classic',bg=(!classic&&t.bg)?storedImageDisplaySource(t.bg):(!classic?OFF_BLACK_BG:'');
  return {cls:(classic?' off-classic':'')+(bg?' hasbg':''),
    style:`--offc-me:${t.me};--offc-me-ink:${t.meInk};--offc-them:${t.them};--offc-them-ink:${t.themInk};--offc-nar:${t.nar};`+`--offc-me-soft:${offRgba(t.me,.62)};--offc-them-soft:${offRgba(t.them,.52)};`
      +(bg?`background-image:url(${bg});`:'')};}
function offSkinSet(id,skin){const c=getC(id);if(!c)return;
  offTheme(c).skin=skin==='classic'?'classic':'glass';save();closeModal();render();
  setTimeout(()=>offAppearance(id),60);}
function offFieldHTML(placeholder){return `<div class="off-field"><textarea id="off_in" rows="1" placeholder="${esc(typeof offInputPlaceholder==='function'?offInputPlaceholder(placeholder):placeholder)}" onkeydown="if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();offSay();}"></textarea></div>`;}
function offAppearance(id){const c=getC(id);if(!c)return;const t=offTheme(c);
  const row=(k,label,hint)=>`<div class="field"><label>${label}${hint?`<small style="display:block;color:#888">${hint}</small>`:''}</label>`
    +`<div class="avline"><input type="color" value="${t[k]}" oninput="offThemeSet('${id}','${k}',this.value)" style="width:56px;height:34px;padding:0;border:1px solid #38383a;border-radius:8px;background:#2c2c2e">`
    +`<span style="color:#8a8a8f;font-size:12px">${t[k]}</span></div></div>`;
  const glass=t.skin!=='classic';
  openModal(`<h3>线下外观</h3>
   ${glass?`<div class="hint">和信息页同一套玻璃：气泡是磨砂的，边上那条高光会跟着背景的颜色走。颜色改完立刻就能看见。</div>
   <div class="field"><label>聊天背景<small style="display:block;color:#888">按原图质量存（2600px），不会压糊</small></label>
     <div class="avline"><button class="btn imblue" style="flex:1" onclick="offBgPick('${id}')">选图片</button>
     ${t.bg?`<button class="btn g" style="flex:1;margin-left:8px" onclick="offBgClear('${id}')">恢复默认</button>`:''}</div></div>
   ${row('me','我的气泡')}
   ${row('meInk','我的字')}
   ${row('them','ta的气泡')}
   ${row('themInk','ta的字')}
   ${row('nar','旁白的字','就是中间那些动作描写')}`
   :`<div class="hint">「原来的」就是改之前那一套，样子是固定的：黑底、方一点的气泡、宋体旁白。背景和配色只对「玻璃」生效，切回玻璃就能接着调。</div>`}
   <div class="btns"><button class="btn g" onclick="offThemeReset('${id}')">配色恢复默认</button><button class="btn p" onclick="closeModal()">好了</button></div>`);}
function offThemeSet(id,key,val){const c=getC(id);if(!c||!(key in OFF_THEME_DEF))return;
  const t=offTheme(c);t[key]=offColorOk(val,OFF_THEME_DEF[key]);save();
  /* 不重画整页：直接改舞台上那个变量，弹窗不会被关掉，她能一边调一边看 */
  const st=document.querySelector('.offstage');if(st){st.style.setProperty('--offc-'+({me:'me',meInk:'me-ink',them:'them',themInk:'them-ink',nar:'nar'})[key],t[key]);if(key==='me'||key==='them')st.style.setProperty('--offc-'+key+'-soft',offRgba(t[key],key==='me'?.62:.52));}}
function offThemeReset(id){const c=getC(id);if(!c)return;const t=offTheme(c);
  for(const k in OFF_THEME_DEF)t[k]=OFF_THEME_DEF[k];save();closeModal();render();toast('配色恢复默认了');}
function offBgPick(id){const c=getC(id);if(!c)return;
  pickFile('image/*',async f=>{let src='';try{src=await compressChatBackground(f);}catch(_){}
    if(!src){toast('这张图读不出来，换一张');return;}
    offTheme(c).bg=src;save();closeModal();render();toast('线下背景换好了');});}
function offBgClear(id){const c=getC(id);if(!c)return;offTheme(c).bg='';save();closeModal();render();toast('已恢复默认背景');}
function offData(id){S.offline=S.offline&&typeof S.offline==='object'&&!Array.isArray(S.offline)?S.offline:{};let o=S.offline[id];if(!o||typeof o!=='object'||Array.isArray(o))o=S.offline[id]={};o.loc=typeof o.loc==='string'?o.loc:'';o.when=typeof o.when==='string'?o.when:'';o.msgs=Array.isArray(o.msgs)?o.msgs:[];o.memory=Array.isArray(o.memory)?o.memory:[];o.history=Array.isArray(o.history)?o.history:[];o.started=!!o.started;o.daypart=typeof o.daypart==='string'?o.daypart:'';return o;}
function cohabRoot(){S.cohabitation=S.cohabitation&&typeof S.cohabitation==='object'&&!Array.isArray(S.cohabitation)?S.cohabitation:{};const r=S.cohabitation;r.homes=r.homes&&typeof r.homes==='object'&&!Array.isArray(r.homes)?r.homes:{};if(typeof r.enabled!=='boolean')r.enabled=false;if(typeof r.paused!=='boolean')r.paused=!r.enabled;return r;}
function cohabDefaultCid(){const r=cohabRoot(),valid=id=>id&&getC(id)&&!getC(id).deleted;if(valid(r.cid))return r.cid;const couple=S.couple&&valid(S.couple.cid)&&S.couple.cid,first=(S.contacts||[]).find(c=>c&&!c.deleted&&!c.blocked);r.cid=couple||first&&first.id||'';return r.cid;}
function cohabRepairRows(rows,kind,base){if(!Array.isArray(rows))return[];return rows.map((row,index)=>{if(typeof row==='string'||typeof row==='number')row={text:String(row)};if(!row||typeof row!=='object'||Array.isArray(row))return null;row.text=String(row.text==null?'':row.text).trim();if(!row.text)return null;if(!row.id)row.id=uid();if(!Number.isFinite(+row.time)||+row.time<=0)row.time=base+index;if(kind==='message'&&!['me','ta','旁白','日期'].includes(row.who))row.who=row.role==='user'?'me':row.role==='assistant'?'ta':'旁白';if(kind==='summary'){row.ts=Math.max(1,+row.ts||+row.time||base+index);row.imp=Math.max(1,Math.min(5,+row.imp||3));row.rounds=Math.max(1,+row.rounds||1);row.mode=row.mode==='split'?'split':'single';}return row;}).filter(Boolean);}
function cohabData(id){const r=cohabRoot();id=id||cohabDefaultCid();if(!id)return null;let d=r.homes[id];if(!d||typeof d!=='object'||Array.isArray(d))d=r.homes[id]={};const legacyBase=Math.max(1,+d.startedAt||+d.phaseAt||Date.now()-Math.max(1000,(Array.isArray(d.msgs)?d.msgs.length:0)+100));d.msgs=cohabRepairRows(d.msgs,'message',legacyBase);d.notices=cohabRepairRows(d.notices,'notice',legacyBase);d.summaries=cohabRepairRows(d.summaries,'summary',legacyBase);d.summarySeq=Math.max(0,+d.summarySeq||0);d.summaryRetryAt=Math.max(0,+d.summaryRetryAt||0);d.msgSeq=Math.max(0,+d.msgSeq||0);d.msgs.forEach((m,index)=>{if(!(+m.cohabSeq>0))m.cohabSeq=++d.msgSeq;else d.msgSeq=Math.max(d.msgSeq,+m.cohabSeq);if(!Number.isFinite(+m.time)||+m.time<=0)m.time=legacyBase+index;});d.phase=['home','work','returning','away','together-away'].includes(d.phase)?d.phase:'home';d.activity=cohabActivityClean(d.activity)||cohabPhaseDefaultActivity(d.phase);d.place=cohabPlaceClean(d.place)||(d.phase==='home'&&/^在/.test(d.activity)?cohabPlaceClean(d.activity):'');d.placeAt=Math.max(0,+d.placeAt||0);d.phaseAt=+d.phaseAt||Date.now();d.startedAt=+d.startedAt||Date.now();d.nextAt=+d.nextAt||0;d.nextPhase=['home','work','returning','away','together-away'].includes(d.nextPhase)?d.nextPhase:'';d.unreadReturn=!!d.unreadReturn;d.returnedAt=+d.returnedAt||0;d.phoneInspectDueAt=Math.max(0,+d.phoneInspectDueAt||0);if(d.phoneInspection&&Date.now()-(+d.phoneInspection.at||0)>120000)d.phoneInspection=null;if(d.pendingArrival&&typeof d.pendingArrival!=='object')d.pendingArrival=null;cohabSettings(d);return d;}
function cohabSettings(d){d=d&&typeof d==='object'?d:{};const x=d.settings&&typeof d.settings==='object'&&!Array.isArray(d.settings)?d.settings:d.settings={},apiRoutes=['follow','0','1','2','3'];x.contextLimit=Math.max(10,Math.min(80,Math.round(+x.contextLimit||+(S.settings&&S.settings.offHist)||30)));x.summaryRounds=x.summaryRounds===0?0:Math.max(1,Math.min(40,Math.round(+x.summaryRounds||6)));x.summaryMemoryLimit=Math.max(1,Math.min(20,Math.round(+x.summaryMemoryLimit||8)));x.memoryCap=x.memoryCap===0?0:Math.max(20,Math.min(2000,Math.round(+x.memoryCap||200)));x.summaryMode=['single','split'].includes(x.summaryMode)?x.summaryMode:(S.settings&&S.settings.offSummaryMode==='single'?'single':'split');x.replyModel=['role','main','aux'].includes(x.replyModel)?x.replyModel:(['role','main','aux'].includes(x.replyRoute)?x.replyRoute:'role');x.replyApiRoute=apiRoutes.includes(String(x.replyApiRoute))?String(x.replyApiRoute):'follow';x.summaryModel=['reply','main','aux'].includes(x.summaryModel)?x.summaryModel:(['reply','main','aux'].includes(x.summaryRoute)?x.summaryRoute:(S.settings&&S.settings.offSummaryModel==='aux'?'aux':'main'));x.summaryApiRoute=['reply',...apiRoutes].includes(String(x.summaryApiRoute))?String(x.summaryApiRoute):'reply';x.tapAdvance=x.tapAdvance===true;return x;}
function cohabContextLimit(d){return cohabSettings(d).contextLimit;}
function cohabMemoryCap(d){return cohabSettings(d).memoryCap;}
function cohabSummaryRoundLimit(d){return cohabSettings(d).summaryRounds;}
function cohabSummaryMemoryLimit(d){return cohabSettings(d).summaryMemoryLimit;}
function cohabSummaryMode(d){return cohabSettings(d).summaryMode;}
function cohabModelLabel(model){return({role:'跟随角色模型',reply:'跟随对话模型',main:'主模型',aux:'副模型'})[model]||'跟随角色模型';}
function cohabApiRouteLabel(route){if(route==='reply')return'跟随对话路线';if(route==='follow')return'跟随微信路线';const i=parseInt(route,10);return Number.isInteger(i)&&CHAT_ROUTE_NAMES[i]?CHAT_ROUTE_NAMES[i]:'跟随微信路线';}
function cohabReplyAux(c,d){const model=cohabSettings(d).replyModel;return model==='aux'||model==='role'&&c.model==='aux';}
function cohabReplyRouteIndex(d){const route=cohabSettings(d).replyApiRoute;return route==='follow'?null:parseInt(route,10);}
function cohabSummaryAux(c,d){const model=cohabSettings(d).summaryModel;if(model==='reply')return cohabReplyAux(c,d);return model==='aux';}
function cohabSummaryRouteIndex(d){const x=cohabSettings(d),route=x.summaryApiRoute;if(route==='reply')return cohabReplyRouteIndex(d);return route==='follow'?null:parseInt(route,10);}
function cohabSettingsBrief(d){const x=cohabSettings(d);return x.contextLimit+'条 · '+(x.summaryRounds?x.summaryRounds+'轮总结':'总结关闭')+' · '+cohabModelLabel(x.replyModel)+' / '+cohabApiRouteLabel(x.replyApiRoute);}
function cohabSettingSet(id,key,value,el){const d=cohabData(id);if(!d)return;const x=cohabSettings(d);if(key==='contextLimit')x.contextLimit=Math.max(10,Math.min(80,Math.round(+value||30)));else if(key==='summaryRounds')x.summaryRounds=Math.max(0,Math.min(40,Math.round(+value||0)));else if(key==='summaryMemoryLimit')x.summaryMemoryLimit=Math.max(1,Math.min(20,Math.round(+value||8)));else if(key==='memoryCap')x.memoryCap=(String(value).trim()==='0')?0:Math.max(20,Math.min(2000,Math.round(+value||200)));else if(key==='summaryMode'&&['single','split'].includes(value))x.summaryMode=value;else if(key==='replyModel'&&['role','main','aux'].includes(value))x.replyModel=value;else if(key==='replyApiRoute'&&['follow','0','1','2','3'].includes(String(value)))x.replyApiRoute=String(value);else if(key==='summaryModel'&&['reply','main','aux'].includes(value))x.summaryModel=value;else if(key==='summaryApiRoute'&&['reply','follow','0','1','2','3'].includes(String(value)))x.summaryApiRoute=String(value);else if(key==='tapAdvance'){x.tapAdvance=String(value)==='1'||value===true;if(!x.tapAdvance)cohabTapRelease();}else return;if(el&&/Limit|Rounds/.test(key))el.value=x[key];const brief=document.getElementById('cohab-settings-brief');if(brief)brief.textContent=cohabSettingsBrief(d);save();}
function cohabMemoryKey(x){return encodeURIComponent([x&&x.id||'',+((x&&x.ts)||0),String(x&&x.text||'').slice(0,80)].join('|'));}
function cohabMemoryEnsureIds(d){let changed=false;(d&&d.summaries||[]).forEach(x=>{if(x&&typeof x==='object'&&!x.id){x.id=uid();changed=true;}});return changed;}
function cohabMemoryFindIndex(d,key){key=String(key||'');return(d&&d.summaries||[]).findIndex(x=>String(x&&x.id||'')===key||cohabMemoryKey(x)===key);}
function cohabMemoryScrollTop(){const sheet=$('#modalSheet');return sheet?sheet.scrollTop:0;}
function cohabMemoryRestoreScroll(top){top=Math.max(0,+top||0);const restore=()=>{const sheet=$('#modalSheet');if(sheet)sheet.scrollTop=Math.min(top,Math.max(0,sheet.scrollHeight-sheet.clientHeight));};restore();requestAnimationFrame(()=>{restore();requestAnimationFrame(restore);});}
function cohabMemorySetImp(id,key,n){const d=cohabData(id),i=cohabMemoryFindIndex(d,key);if(!d||i<0)return;n=Math.max(1,Math.min(5,parseInt(n,10)||3));const top=cohabMemoryScrollTop();d.summaries[i].imp=n;save();cohabMemoryOpen(id,{scrollTop:top});toast('已设为 '+n+' 星');}
function cohabMemoryPrune(d,cap){if(+cap===0)return;/* 0 表示不限，交给用户自己清理 */cap=Math.max(1,+cap||200);const rows=d&&d.summaries||[];while(rows.length>cap){const i=rows.findIndex(x=>(+x.imp||3)<5);if(i<0)break;rows.splice(i,1);}return rows;}
async function cohabMemoryDelete(id,key){const d=cohabData(id);if(!d||cohabMemoryFindIndex(d,key)<0)return;const top=cohabMemoryScrollTop();if(!await uiConfirm('删除这条共同生活记忆？\n\n只删除这条总结，不会删除共同生活原聊天。'))return;const i=cohabMemoryFindIndex(d,key);if(i<0){toast('这条记忆已经不存在');return;}d.summaries.splice(i,1);save();cohabMemoryOpen(id,{scrollTop:top});toast('共同生活记忆已删除');}
