function cohabTripContext(c,d){if(!c)return'';const rows=cohabTripRows(c).slice(-8);if(!rows.length)return'';const now=Date.now(),lines=rows.map(tr=>{const when=fmtDT(+tr.departAt||+tr.ts||now),route=(tr.from||'共同住处')+'→'+(tr.to||'目的地'),flight=tr.no?('，航班 '+tr.no):'';if(tr.status==='upcoming')return '· 已订双人行程：'+route+'，'+when+'出发'+flight+'。还没有出发。';if(tr.status==='traveling')return '· 双人行程进行中：已于 '+when+' 从'+(tr.from||'共同住处')+'出发前往'+tr.to+flight+'。';if(tr.status==='done')return '· 已完成的双人旅行：'+when+'从'+(tr.from||'共同住处')+'出发，去过「'+tr.to+'」'+flight+'。';return '· 已取消的双人行程：'+route+'，原定 '+when+flight+'。';});return '\n\n# 共同生活双人行程（小鱼旅行后台真实订单）\n'+lines.join('\n')+'\n这些订单没有发到微信，也不是角色气泡；但你本人知道订了什么、何时出发、去过哪里。未到出发时间绝不能说已经出发，到点后必须承认状态已经推进。';}
function cohabTripDateAt(dateRaw,timeRaw,now){now=+now||Date.now();const raw=String(dateRaw||'').trim(),tm=String(timeRaw||'').trim().match(/^([01]\d|2[0-3]):([0-5]\d)$/);if(!tm)return null;let y,m,d,explicitYear=false,hit=raw.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);if(hit){explicitYear=true;y=+hit[1];m=+hit[2];d=+hit[3];}else{hit=raw.match(/^(\d{1,2})\s*月\s*(\d{1,2})\s*日?$/);if(!hit)return null;const base=new Date(now);y=base.getFullYear();m=+hit[1];d=+hit[2];}const make=year=>new Date(year,m-1,d,+tm[1],+tm[2],0,0),valid=x=>x.getFullYear()===y&&x.getMonth()===m-1&&x.getDate()===d;let at=make(y);if(!valid(at))return null;if(!explicitYear&&at.getTime()<now-60000){y++;at=make(y);if(!valid(at))return null;}const value=at.getTime();if(value<now-60000||value>now+366*86400000)return null;return{date:y+'-'+tvP2(m)+'-'+tvP2(d),dep:tm[1]+':'+tm[2],departAt:value};}
function cohabTripPlan(c,to,dateRaw,timeRaw,now){to=String(to||'').replace(/[\[\]【】|｜]/g,'').trim().slice(0,40);if(!c||!to)return{error:'目的地不完整'};if(S.settings&&S.settings.timeAware===false)return{error:'时间感知已关闭，不能创建准点行程'};const from=meHomeCity()||charHomeCity(c)||'苏州';if(tvSameCity(from,to))return{error:'出发地和目的地相同'};const dt=cohabTripDateAt(dateRaw,timeRaw,now);if(!dt)return{error:'日期或出发时间无效'};const seed=(dt.date+'|'+dt.dep+'|'+from+'|'+to+'|'+c.id).split('').reduce((s,ch)=>s+ch.charCodeAt(0),0),intl=tvCity(from).i||tvCity(to).i,durationHours=intl?8+Math.abs(seed)%7:1+Math.abs(seed)%3,price=tvPrice(from,to,'economy')*2;return{from,to,date:dt.date,dep:dt.dep,departAt:dt.departAt,arriveAt:dt.departAt+durationHours*3600000,durationHours,no:tvFlightNo(seed),price};}
