function cohabSummaryCompletedRounds(rows){let waiting=false,n=0;(rows||[]).forEach(m=>{const mine=m.who==='me'||m.who==='旁白'&&m.source==='me',theirs=m.who==='ta'||m.who==='旁白'&&m.source!=='me';if(mine)waiting=true;else if(theirs&&waiting){n++;waiting=false;}});return n;}
