function cohabMemoryAfterPrompt(c){if(!c||(typeof cohabWechatState==='function'&&cohabWechatState(c)))return'';const r=S.cohabitation,d=r&&r.homes&&r.homes[c.id];if(!d||!(d.summaries||[]).length)return'';const body=cohabMemoryPrompt(d,(msgs(c.id)||[]).slice(-cohabContextLimit(d)).map(msgToText).join('\n'));if(!body)return'';return body.replace('# 共同生活已经自动整理的旧记忆','# 你们一起生活过的那段时间留下的记忆')+'\n现在共同生活已经结束或暂停，你们不再处于同居状态；这些只是真实发生过的往事，可以自然提起、回忆、想念，但不要说成此刻正在一起。';}
