async function cohabSummarize(id,d,opt){d=d||cohabData(id);opt=opt||{};const c=getC(id),rows=cohabSummaryRows(d),roundLimit=cohabSummaryRoundLimit(d),rounds=cohabSummaryCompletedRounds(rows);if(!d||!c||!rows.length||_cohabSummaryBusy.has(id)||!opt.force&&(!roundLimit||Date.now()<d.summaryRetryAt||rounds<roundLimit))return 0;const targetSeq=Math.max(...rows.map(m=>+m.cohabSeq||0)),transcript=cohabSummaryTranscript(rows,c),rule=offSummaryPerspectiveRule(c),aux=cohabSummaryAux(c,d),routeIndex=cohabSummaryRouteIndex(d),mode=cohabSummaryMode(d),split=mode==='split',format=split?'按不同的重要事件拆成1到8条独立记忆；内容少时宁可只有1条，也不重复、不凑数。每条60到180个中文字。只输出JSON对象：{"items":[{"text":"第一人称记忆","importance":1到5}]}，不要Markdown或解释。':'写成一整段80到300个中文字，只输出正文，不要标题、列表、括号或格式说明。',messages=[{role:'system',content:'你就是「'+(c.remark||c.name)+'」本人。把下面共同生活的新内容整理成可长期记住的生活记忆。只记录真正新增的重要事实、双方说清楚的话、约定、情绪或关系变化；普通起身、走路、坐下、拿东西、环境和姿势等动作描写不要写进记忆。'+rule+format},{role:'user',content:transcript}];_cohabSummaryBusy.add(id);try{let raw=await chatAPI(messages,{aux,routeIndex,max:split?1500:620,temp:.2,complete:true,allowSessionModel:true}),items=cohabSummaryItems(raw,mode);if(!items.length){raw=await chatAPI([...messages,{role:'assistant',content:raw||''},{role:'user',content:split?'上一版JSON、视角或内容不合格。严格按指定JSON返回1到8条角色第一人称记忆；内容少就只写1条，删除第三人称旁白、普通动作流水账和原文没有的事。':'上一版视角或格式不合格。严格改成角色第一人称“我”的一整段生活记忆，删除第三人称旁白、普通动作流水账和原文没有的事。'}],{aux,routeIndex,max:split?1500:620,temp:.08,complete:true,allowSessionModel:true});items=cohabSummaryItems(raw,mode);}if(!items.length)throw new Error('共同生活总结格式不合格');const batchId=uid(),now=Date.now();items.forEach(x=>d.summaries.push({id:uid(),batchId,ts:now,fromSeq:+rows[0].cohabSeq||0,toSeq:targetSeq,rounds:Math.max(1,rounds),mode,text:x.text,imp:x.imp}));cohabMemoryPrune(d,cohabMemoryCap(d));d.summarySeq=targetSeq;d.summaryRetryAt=0;await saveNowAsync();return items.length;}catch(_){d.summaryRetryAt=Date.now()+5*60000;save();return 0;}finally{_cohabSummaryBusy.delete(id);}}
