function cohabTapIndicatorSync(){const box=typeof document!=='undefined'&&document.getElementById('offbg');if(!box||!box.closest('.cohab-stage'))return;const arrows=box.querySelectorAll('.cohab-tap-next'),t=_cohabTap,active=!!(t&&_off&&_off.mode==='cohab'&&_off.id===t.id&&cur().p==='off'&&!_offSel&&!document.querySelector('.cohab-away-panel'));if(!active){arrows.forEach(a=>a.remove());return;}if(!arrows.length)box.insertAdjacentHTML('beforeend',cohabTapNextHTML(t.id));else for(let i=1;i<arrows.length;i++)arrows[i].remove();}

function cohabTapHandle(e){const t=_cohabTap;if(!t||!e)return;const el=e.target&&e.target.closest?e.target:null;if(!el||!el.closest('.cohab-stage'))return;
  if(el.closest('button,a,input,textarea,select,label,summary,details,.cohab-settings,.inputbar,.offselect,.cohab-away-panel,.cohab-return-banner,.cohab-meta,.nav'))return;/* 按钮、输入框照常用 */
  e.preventDefault();e.stopPropagation();
  if(Date.now()<t.revealEnd&&t.item&&t.item._reveal){t.item._reveal=false;t.revealEnd=0;offRender();return;}/* 这一句还在一个字一个字出，先让它一下出完 */
  cohabTapRelease();}
if(typeof document!=='undefined')document.addEventListener('click',cohabTapHandle,true);
function offRevealTiming(m){const n=Math.max(1,Array.from(String(m&&m.text||'')).length),nar=m&&m.who==='旁白',reduce=typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches,step=reduce?0:50,reveal=reduce?120:Math.round(step*(n-1)+480),hold=Math.max(1100,Math.min(nar?4200:3200,900+n*(nar?22:18)));return{step,reveal,hold,total:reveal+hold};}
function offRevealText(m){let text=m&&(m.who==='me'||m.source==='me')?String(m.text||''):offlineStripMoodTags(m&&m.text);if(m&&m.who==='ta'&&m.source!=='me'){const part=offResponsePart(text);if(part.kind==='nar')text=part.text;}if(!m||!m._reveal)return esc(text);const step=+m._revealStep||0;return Array.from(text).map((ch,i)=>ch==='\n'?'<br>':'<span class="offglyph" style="animation-delay:'+Math.round(i*step)+'ms">'+(ch===' '?'&nbsp;':esc(ch))+'</span>').join('');}
const OFFLINE_ROUTINE_TOPICS=[
  ['task','任务/作业',/任务|任务便签|作业|打卡|做完|完成.{0,5}(了吗|没有|没|了没)|交.{0,3}(作业|任务)|该做的.{0,5}(做|完成)/],
  ['meal','吃饭',/吃饭|吃过|吃了|吃东西|吃点|饭吃|早餐|早饭|午饭|晚饭|饿不饿|饿了|别饿/],
  ['sleep','睡觉',/睡觉|睡了|睡没|睡着|困不困|早点睡|熬夜|晚安|起床|醒了|休息了吗/],
  ['where','在干嘛',/在干嘛|干什么呢|做什么呢|在哪儿|在哪里|到家.{0,3}(没|吗)|回家.{0,3}(没|吗)/],
  ['miss','想念/失联',/想我|想不想我|有没有想|怎么不找我|不来找我|没理我|不回我|又消失/],
  ['health','喝水/身体',/喝水|多喝|身体怎么样|还疼|好点了吗|难受吗|不舒服.{0,3}(吗|没)/],
  ['report','报备',/报备|告诉我去哪|去了哪里|到哪了|和谁在一起|跟谁|几点回来/],
  ['phone','少玩手机',/少玩手机|别玩手机|刷手机|玩多久|玩手机超时|眼睛休息|别再刷/]
];
function offRepeatNorm(text){return String(text||'').toLowerCase().replace(/[\s，。、！？!?,.~～…：:；;（）()「」『』“”'"\-—]/g,'');}
function offRoutineTopics(text){text=String(text||'').replace(/\s+/g,'');return OFFLINE_ROUTINE_TOPICS.filter(x=>x[2].test(text)).map(x=>x[0]);}
function offRoutineLabel(key){const x=OFFLINE_ROUTINE_TOPICS.find(v=>v[0]===key);return x?x[1]:key;}
function offRepeatSimilarity(a,b){const aa=new Set(offRepeatNorm(a).split('').filter(Boolean)),bb=new Set(offRepeatNorm(b).split('').filter(Boolean));if(!aa.size||!bb.size)return 0;let n=0;aa.forEach(x=>{if(bb.has(x))n++;});return n/Math.max(aa.size,bb.size);}
function offNarrationText(part){const raw=String(part||'').trim();if(!raw)return null;let inner=raw,wrapped=false;if(/^[（(【][\s\S]*[）)】]$/.test(raw)){inner=raw.slice(1,-1).trim();wrapped=true;}else if(/^\[[\s\S]*\]$/.test(raw))inner=raw.slice(1,-1).trim();else if(/^[（(【]/.test(raw)&&!/[）)】]$/.test(raw)){inner=raw.slice(1).trim();wrapped=true;}const labeled=inner.match(/^(?:动作旁白|旁白|动作描写|场景描写|场景|叙述)\s*[|｜:：]\s*([\s\S]+)$/);if(labeled)return labeled[1].replace(/^[（(【]+|[）)】]+$/g,'').trim()||null;return wrapped?inner:null;}
function offImplicitNarrationText(part){const raw=String(part||'').trim();if(!raw||/[？?]/.test(raw)||/[“”「」『』]/.test(raw))return null;const actor=/^(?:他|她|两人|男人|女人|少年|少女|青年|女孩|男孩|对方)(?:的|们|正|又|仍|却|没|不|已经|只是|只|甚至|并|还|忽然|突然|缓缓|慢慢|微微|抬|低|看|望|盯|走|跑|站|坐|躺|靠|伸|收|握|松|停|转|侧|皱|笑|叹|沉|咬|抿|压|抽|拉|推|把|将)/.test(raw),detail=/^(?:视线|目光|眼底|眼睛|嘴角|眉眼|眉头|喉结|手指|掌心|肩膀|脚步|呼吸|声音|语气|身影|头发|鞋底|行李箱|灯光|夜色|风|雨)/.test(raw),motion=/(?:抬|低|看见|看向|看着|看了|望|盯|扫|走|跑|站|坐|躺|靠|伸|收|握|攥|松|停|转|侧|皱|笑|叹|沉|咬|抿|压|抽|拉|推|砸|滚|亮|垂|贴|落|响|颤|僵|绷|缩|顿|穿|锁|滑|呼吸|照得|显得|像一颗)/.test(raw),shortAction=/^(?:他|她|两人)(?:没动|没有动|一动不动|沉默(?:了|着)?|没说话|停下脚步|抬起头|低下头|转过身)[。！…]*$/.test(raw);const sceneDetail=raw.length>=30&&/(?:他|她)的(?:眼|睫毛|手|肩|嘴|喉|呼吸)/.test(raw)&&(motion||/(?:湿了|红了|泪|深眸|眼眸)/.test(raw)),briefAction=/^(?:他|她)(?:(?:没有|没)(?:擦|动|说话)|只是看着|抬起头|低下头|转过身)(?:[。！…]|$)/.test(raw);return actor&&raw.length>=18&&motion||shortAction||detail&&motion||sceneDetail||briefAction?raw.replace(/[】）)]$/,'').trim():null;}
function offResponsePart(part){part=String(part||'').trim();const narration=offNarrationText(part);if(narration!=null)return{kind:'nar',text:narration};const implicit=offImplicitNarrationText(part);return implicit==null?{kind:'talk',text:part}:{kind:'nar',text:implicit,implicit:true};}
function offResponseParts(text){text=offlineStripMoodTags(roleVisibleEnvelopeText(text));const out=[];splitBubbles(text).forEach(line=>{const whole=offResponsePart(line);if(whole.kind==='nar'){out.push(whole);return;}splitActions(line).forEach(part=>{part=String(part||'').trim();if(part)out.push(offResponsePart(part));});});return out;}
function offGeneratedTalk(text){return offResponseParts(text).filter(x=>x.kind==='talk').map(x=>x.text);}
function offRecentParts(o){return(o&&o.msgs||[]).filter(m=>m&&((m.who==='旁白'&&m.source!=='me')||m.who==='ta')).slice(-80).map(m=>({kind:m.who==='旁白'?'nar':'talk',text:String(m.text||'')})).filter(x=>x.text);}
function offCrossRepeat(part,old,currentInput,strict){if(!part||!old||part.kind!==old.kind)return false;const n=offRepeatNorm(part.text),p=offRepeatNorm(old.text),cur=offRepeatNorm(currentInput);if(!n||!p)return false;const userRaised=part.kind==='talk'&&((n.length>=2&&cur.includes(n))||(p.length>=2&&cur.includes(p)));if(n===p)return n.length>=(part.kind==='nar'?6:4)&&!userRaised;if(strict)return part.kind==='nar'&&Math.min(n.length,p.length)>=16&&offRepeatSimilarity(n,p)>=.9;const min=Math.min(n.length,p.length);if(part.kind==='talk'&&!userRaised&&min>=4&&(n.includes(p)||p.includes(n)))return true;return min>=(part.kind==='nar'?16:8)&&offRepeatSimilarity(n,p)>=(part.kind==='nar'?.78:.82)&&!userRaised;}
function offDedupeItems(items,o,currentInput){const list=items||[],seen=new Set(),recent=offRecentParts(o),cur=offRepeatNorm(currentInput),replayed=list.some(item=>{const kind=item&&item.who==='旁白'?'nar':'talk';return recent.some(old=>offCrossRepeat({kind,text:item&&item.text},old,currentInput,true));});return list.filter(item=>{const norm=offRepeatNorm(item&&item.text),kind=item&&item.who==='旁白'?'nar':'talk',key=kind+'|'+norm;if(norm.length>=4&&seen.has(key))return false;if(norm.length>=4)seen.add(key);if(recent.some(old=>offCrossRepeat({kind,text:item.text},old,currentInput,true)))return false;if(replayed&&norm.length>=2&&!cur.includes(norm)&&recent.some(old=>old.kind===kind&&offRepeatNorm(old.text)===norm))return false;return true;});}
