function offReplyItems(text){text=rolePublicText(offlineStripMoodTags(roleVisibleEnvelopeText(text)));const items=[];splitBubbles(text||'').forEach(l=>{l=normTag(l);if(LEAKRE.test(l)||isOOCLine(l)||isRefusal(l))return;const whole=offResponsePart(l);if(whole.kind==='nar'){items.push({id:uid(),who:'旁白',source:'ta',text:whole.text});return;}l=l.replace(/\[[^\]]*\]/g,'').trim();if(!l)return;splitActions(l).forEach(p=>{p=(p||'').trim();if(!p)return;const part=offResponsePart(p);items.push({id:uid(),who:part.kind==='nar'?'旁白':'ta',source:'ta',text:part.text});});});return items;}
